<style>
.arc-sup{--edge:#344a62;--field:#192c41;--accent:#b7806c;min-height:0;flex:1 1 auto;color:#eaf1f9;background:#172536;padding:12px;font:12px 'Segoe UI',Arial,sans-serif;box-sizing:border-box}.arc-sup *{box-sizing:border-box}.arc-sup [hidden]{display:none!important}.arc-sup :is(select,input,button){font:inherit}.arc-sup select,.arc-sup input{background:var(--field);color:inherit;border:1px solid var(--edge);padding:9px;border-radius:6px;max-width:100%}.arc-sup h2{font-size:15px;margin:18px 0 8px}.arc-sup-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}.arc-sup-grid button{background:#21334a;color:#eaf1f9;border:1px solid var(--edge);border-radius:9px;min-height:85px;padding:15px;display:flex;flex-direction:column;gap:8px;align-items:flex-start;text-align:left;cursor:pointer}.arc-sup-grid button:hover{border-color:var(--accent)}.arc-sup-grid i{color:var(--accent);font-size:19px}.arc-sup-dialog{width:min(520px,calc(100vw - 22px));border:1px solid #49617b;border-radius:12px;background:#1b2d44;color:#edf4fc;padding:0;box-shadow:0 20px 60px #0009}.arc-sup-dialog::backdrop{background:#071321bb}.arc-sup-dialog header{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#233950}.arc-sup-dialog header h3{margin:0;font-size:15px}.arc-sup-dialog button{padding:9px 12px;border:1px solid #50627a;background:#263f59;color:#fff;border-radius:7px;cursor:pointer}.arc-sup-dialog button.primary{background:var(--accent);border-color:var(--accent)}.arc-sup-body{padding:14px;display:grid;gap:12px}.arc-sup-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}.arc-sup-form{display:grid;gap:9px}.arc-sup-form label{display:grid;gap:5px}.arc-sup-form fieldset{border:1px solid var(--edge);display:flex;flex-wrap:wrap;gap:10px}.arc-sup-form fieldset label{display:flex}.arc-sup-status{min-height:20px;color:#b9cfdf}.arc-sup a{color:#efb49b}@media(max-width:650px){.arc-sup{padding:6px}}
</style>
