<dialog class="arc-sup-dialog" id="sup-modal"><header><h3 id="sup-title">Serviço</h3><button type="button" data-close aria-label="Fechar">×</button></header><div class="arc-sup-body"><p id="sup-feedback" class="arc-sup-status" role="status"></p><div class="arc-sup-actions" id="sup-choice"><button type="button" id="sup-now" class="primary">Executar agora</button><button type="button" id="sup-plan">Criar rotina</button></div><form id="sup-form" class="arc-sup-form" hidden><label>Início<input type="datetime-local" name="starts_at" required></label><label>Repetição<select name="recurrence"><option value="once">Uma vez</option><option value="weekdays">Dias da semana</option><option value="interval">Por intervalo</option></select></label><label id="sup-interval" hidden>Intervalo (minutos)<input type="number" name="interval_minutes" value="60" min="15" max="10080"></label><fieldset id="sup-days" hidden><legend>Dias da semana</legend><?php foreach([1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',7=>'Dom'] as $day=>$label):?><label><input type="checkbox" name="weekdays" value="<?=$day?>"> <?=$label?></label><?php endforeach;?></fieldset><label>Data de término (opcional)<input type="datetime-local" name="ends_at"></label><label id="sup-password-label" hidden>Senha para comandos de energia<input name="password" type="password" autocomplete="current-password"></label><label id="sup-confirm-label" hidden><input name="confirmed" type="checkbox"> Confirmo a operação de energia</label><div class="arc-sup-actions"><button type="button" id="sup-back">Voltar</button><button type="submit" class="primary">Salvar rotina</button></div></form></div></dialog>
</section>
<script>
(()=>{'use strict';const root=document.getElementById('arc-sup'),gestor=document.getElementById('sup-gestor'),modal=document.getElementById('sup-modal'),form=document.getElementById('sup-form'),feedback=document.getElementById('sup-feedback'),choice=document.getElementById('sup-choice');if(!root)return;const base=root.dataset.base,network=Number(root.dataset.network),csrf=root.dataset.csrf;let command='',busy=false;
async function send(url,data){const response=await fetch(base+url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({...data,network_id:network,gestor_id:Number(gestor.value),_csrf:csrf})});const json=await response.json();if(!response.ok||!json.ok)throw Error(json.error||'Não foi possível executar a operação.');return json;}
const recurrence=form.elements.recurrence,interval=document.getElementById('sup-interval'),days=document.getElementById('sup-days'),password=document.getElementById('sup-password-label'),confirm=document.getElementById('sup-confirm-label');function updateFields(){interval.hidden=recurrence.value!=='interval';days.hidden=recurrence.value!=='weekdays';const energy=command.startsWith('power_');password.hidden=!energy;confirm.hidden=!energy;}
root.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{command=b.dataset.service;document.getElementById('sup-title').textContent=b.querySelector('strong').textContent;feedback.textContent='Escolha como deseja executar este serviço.';choice.hidden=false;form.hidden=true;form.reset();updateFields();modal.showModal();}));modal.querySelector('[data-close]').addEventListener('click',()=>modal.close());document.getElementById('sup-back').addEventListener('click',()=>{form.hidden=true;choice.hidden=false});document.getElementById('sup-plan').addEventListener('click',()=>{choice.hidden=true;form.hidden=false;const date=new Date(Date.now()+300000);date.setMinutes(date.getMinutes()-date.getTimezoneOffset());form.elements.starts_at.value=date.toISOString().slice(0,16);updateFields()});recurrence.addEventListener('change',updateFields);
document.getElementById('sup-now').addEventListener('click',async()=>{if(busy||!Number(gestor.value))return;if(!window.confirm('Confirmar execução deste comando no computador selecionado?'))return;busy=true;try{const data={command};if(command.startsWith('power_')){data.confirmed=true;data.delay_seconds=5}if(command==='windows_update')data.update_mode='scan';const result=await send('api/api.php?action=network-command',data);feedback.textContent='Comando #'+result.command_id+' enviado; aguarde a confirmação do agente.';}catch(e){feedback.textContent=e.message}finally{busy=false;}});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!Number(gestor.value))return;busy=true;const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const data=Object.fromEntries(new FormData(form));data.command=command;data.weekdays=[...form.querySelectorAll('input[name=weekdays]:checked')].map(x=>Number(x.value));data.confirmed=form.elements.confirmed.checked;await send('api/support.php?action=schedule-save',data);feedback.textContent='Rotina criada. Consulte a Agenda para gerenciar.';form.hidden=true;choice.hidden=false;}catch(err){feedback.textContent=err.message}finally{busy=false;btn.disabled=false;}});
})();
</script>
